package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.View;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.uiautomator.*;
import java.io.File;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.Test;
import static org.junit.Assert.*;

/** Timing fixture and private workday configuration only; no service or physical output. */
public class SleepRhythmFlowTest {
    private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice device=UiDevice.getInstance(i);private SleepRhythmActivity activity;
    private UiObject2 object(String description)throws Exception{UiObject2 found=device.findObject(By.desc(description));if(found==null){new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().description(description));found=device.wait(Until.findObject(By.desc(description)),5000);}assertNotNull(description,found);return found;}
    private void click(String text)throws Exception{UiObject2 found=device.findObject(By.text(text));if(found==null){new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().text(text));found=device.wait(Until.findObject(By.text(text)),5000);}assertNotNull(text,found);found.click();device.waitForIdle();}
    private void launch()throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(SleepRhythmActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,SleepRhythmActivity.class).putExtra("visualReview",true).putExtra("verificationLabel","Timing fixture · no sensor measurements").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_MULTIPLE_TASK));activity=(SleepRhythmActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}assertTrue(device.wait(Until.hasObject(By.descStartsWith("Bedtime range ")),5000));}
    private boolean hasText(View root,String expected){if(root instanceof android.widget.TextView text&&expected.contentEquals(text.getText()))return true;if(root instanceof android.view.ViewGroup group)for(int n=0;n<group.getChildCount();n++)if(hasText(group.getChildAt(n),expected))return true;return false;}
    // A correctly restored contributor scroll can intentionally keep the title off screen.
    // Observe the loaded, focused owner; never seek that title by moving its viewport.
    private View recreatedPresentation(SleepRhythmActivity owner,String expected)throws Exception{View[] result={null};assertTrue("Loaded recreated owner and exact presentation: "+expected,device.wait(new Condition<UiDevice,Boolean>(){public Boolean apply(UiDevice ignored){result[0]=null;i.runOnMainSync(()->{if(owner.isDestroyed()||owner.isFinishing()||!owner.hasWindowFocus())return;View decor=owner.getWindow().getDecorView();if(!decor.isAttachedToWindow()||!decor.isLaidOut()||!decor.isHardwareAccelerated())return;View focused=null;for(View root:android.view.inspector.WindowInspector.getGlobalWindowViews())if(root.isAttachedToWindow()&&root.hasWindowFocus()&&c.getPackageName().equals(root.getContext().getPackageName())){assertNull("Only one focused application window",focused);focused=root;}if(focused!=decor)return;try{java.lang.reflect.Field loaded=SleepRhythmActivity.class.getDeclaredField("loaded");loaded.setAccessible(true);java.lang.reflect.Field resumed=SleepRhythmActivity.class.getDeclaredField("resumed");resumed.setAccessible(true);if(loaded.getBoolean(owner)&&resumed.getBoolean(owner)&&hasText(decor,expected))result[0]=decor;}catch(ReflectiveOperationException invalid){throw new AssertionError(invalid);}});return result[0]!=null;}},5000));return result[0];}
    private void recreate(String expected)throws Exception{SleepRhythmActivity previous=activity;Instrumentation.ActivityMonitor monitor=i.addMonitor(SleepRhythmActivity.class.getName(),null,false);try{i.runOnMainSync(previous::recreate);activity=(SleepRhythmActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);assertNotSame("Recreation supplies a new owner",previous,activity);}finally{i.removeMonitor(monitor);}assertTrue("Previous owner destroyed",device.wait(new Condition<UiDevice,Boolean>(){public Boolean apply(UiDevice ignored){return previous.isDestroyed();}},5000));previous.awaitReaders(5000);View decor=recreatedPresentation(activity,expected);CountDownLatch committed=new CountDownLatch(1);i.runOnMainSync(()->{assertSame("Recreated decor remains focused",decor,activity.getWindow().getDecorView());assertTrue(activity.hasWindowFocus());decor.getViewTreeObserver().registerFrameCommitCallback(committed::countDown);decor.invalidate();});assertTrue("Recreated presentation committed without moving its viewport",committed.await(5,TimeUnit.SECONDS));i.runOnMainSync(()->{assertTrue("Committed recreated owner remains focused",activity.hasWindowFocus());assertSame(decor,activity.getWindow().getDecorView());});}
    private void finish()throws Exception{SleepRhythmActivity closing=activity;i.runOnMainSync(closing::finish);long until=SystemClock.elapsedRealtime()+5000;boolean[] done={false};while(!done[0]&&SystemClock.elapsedRealtime()<until){i.runOnMainSync(()->done[0]=closing.isDestroyed());if(!done[0])SystemClock.sleep(50);}assertTrue(done[0]);closing.awaitReaders(5000);}
    private void capture(String suffix)throws Exception{capture(suffix,activity);}
    private void capture(String suffix,Activity owner)throws Exception{long until=SystemClock.elapsedRealtime()+5000;CountDownLatch frame=new CountDownLatch(1);boolean[] registered={false};while(!registered[0]&&SystemClock.elapsedRealtime()<until){i.runOnMainSync(()->{if(owner!=null&&!owner.isDestroyed()&&owner.hasWindowFocus()){View decor=owner.getWindow().getDecorView();if(decor.isAttachedToWindow()&&decor.isHardwareAccelerated()){decor.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);decor.invalidate();registered[0]=true;}}});if(!registered[0])SystemClock.sleep(50);}assertTrue("Focused rhythm window",registered[0]);assertTrue(frame.await(5,TimeUnit.SECONDS));File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"rhythm-"+suffix+".png")));}
    private RhythmChart chart(View view){if(view instanceof RhythmChart result)return result;if(view instanceof android.view.ViewGroup group)for(int n=0;n<group.getChildCount();n++){RhythmChart found=chart(group.getChildAt(n));if(found!=null)return found;}return null;}
    private android.widget.ScrollView viewport(View view){if(view instanceof android.widget.ScrollView result)return result;if(view instanceof android.view.ViewGroup group)for(int n=0;n<group.getChildCount();n++){android.widget.ScrollView found=viewport(group.getChildAt(n));if(found!=null)return found;}return null;}
    private int position(){int[] result={0};i.runOnMainSync(()->result[0]=viewport(activity.getWindow().getDecorView()).getScrollY());return result[0];}
    private void awaitPosition(int expected){long until=SystemClock.elapsedRealtime()+5000;while(position()!=expected&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(30);assertEquals("Selected-day viewport remains on return/recreation",expected,position());}
    @Test public void actualSevenNightsWorkdaysPersistRecreateAndEmptyWithoutOutputs()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));
        String name="rhythm-"+UUID.randomUUID()+".db",preferences="rhythm-"+UUID.randomUUID();SharedPreferences prefs=c.getSharedPreferences(preferences,0);Map<String,?> originalPrefs=new HashMap<>(Prefs.of(c).getAll());Records.Factory priorRecords=Records.factory;RhythmSettings.Factory priorSettings=RhythmSettings.factory;java.util.function.LongSupplier priorClock=SleepRhythmActivity.clock;long now=Instant.parse("2026-10-23T12:00:00Z").toEpochMilli();List<Activity> owned=new CopyOnWriteArrayList<>();Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){if(a instanceof SleepRhythmActivity||a instanceof RecordReportActivity)owned.add(a);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(lifecycle);
        String fixture;
        try{
            try(Store store=new Store(c,name)){int[] bedtimes={1350,1395,1370,1420,1340,1375,1385};for(int n=-14;n<7;n++){int bed=bedtimes[Math.floorMod(n,7)];long start=LocalDate.of(2026,10,16).plusDays(n).atTime(bed/60,bed%60).toInstant(ZoneOffset.UTC).toEpochMilli();ContentValues row=new ContentValues();row.put("start",start);row.put("end",start+8*3600000L);row.put("active_ms",8*3600000L);row.put("source","tracked");row.put("origin","local");row.put("zone","UTC");store.getWritableDatabase().insertOrThrow("sessions",null,row);}fixture=store.backup().toString();}
            i.runOnMainSync(()->{Records.factory=context->new Store(context,name);RhythmSettings.factory=context->prefs;SleepRhythmActivity.clock=()->now;});launch();assertTrue(prefs.getAll().isEmpty());assertTrue(device.hasObject(By.text("21 of 30 nights")));assertNotNull(device.findObject(By.descStartsWith("Recorded bedtime chart.")));capture("seven-nights");
            RhythmStats.Night first,observedNight,oldestNight;try(Store store=new Store(c,name)){RhythmStats initial=new RhythmStats(Records.all(store),Prefs.number(c,"statsCutoff",0),31,now);assertEquals("Only the latest seven eligible observations are plotted",7,initial.recent.size());assertEquals("Older evidence fixture creates actual scrollable history",21,initial.nights.size());first=initial.recent.get(0);observedNight=initial.nights.get(1);oldestNight=initial.nights.get(0);}String selected="Selected night "+first.day+", "+first.record.provenance();
            i.runOnMainSync(()->{RhythmChart plot=chart(activity.getWindow().getDecorView());assertNotNull(plot);assertTrue("Chart accepts keyboard/accessibility focus",plot.requestFocusFromTouch());});assertTrue(device.pressKeyCode(android.view.KeyEvent.KEYCODE_DPAD_RIGHT));assertTrue(device.wait(Until.hasObject(By.desc(selected)),5000));
            assertTrue(device.swipe(device.getDisplayWidth()/2,device.getDisplayHeight()*3/4,device.getDisplayWidth()/2,device.getDisplayHeight()/2,20));device.waitForIdle();int selectedPosition=position();assertTrue("Record review leaves a real scrolled rhythm viewport to restore",selectedPosition>0);UiObject2 open=device.findObject(By.text("Open selected night"));assertNotNull("Selected source has an explicit visible Open action",open);assertTrue(open.isEnabled());capture("day-selected");
            Instrumentation.ActivityMonitor reportMonitor=i.addMonitor(RecordReportActivity.class.getName(),null,false);RecordReportActivity report;try{open.click();report=(RecordReportActivity)reportMonitor.waitForActivityWithTimeout(5000);assertNotNull("Open selects the saved record, never latest fallback",report);}finally{i.removeMonitor(reportMonitor);}assertEquals(first.record.id,report.getIntent().getLongExtra("record",0));assertTrue(device.wait(Until.hasObject(By.desc("Edit sleep")),5000));capture("day-report",report);assertTrue(device.pressBack());assertTrue(device.wait(Until.hasObject(By.desc(selected)),5000));activity.awaitReaders(5000);i.waitForIdleSync();awaitPosition(selectedPosition);capture("day-returned");recreate("Open selected night");assertTrue(device.wait(Until.hasObject(By.desc(selected)),5000));awaitPosition(selectedPosition);capture("day-restored");try(Store store=new Store(c,name)){assertEquals("Chart selection and Report navigation are read-only",fixture,store.backup().toString());}
            click("Review observed timing evidence");assertTrue(device.wait(Until.hasObject(By.text("Observed nights, not a chronotype")),5000));assertTrue(device.hasObject(By.text("21 observed main nights · 21 phone-recorded")));assertTrue(device.hasObject(By.textContains("remain unknown.")));assertFalse("Insufficient history is not given an invented owl/lark category",device.hasObject(By.text("Your chronotype")));capture("evidence");
            String observed="Open observed night "+observedNight.day+", "+observedNight.record.provenance();UiObject2 contributor=object(observed);int evidencePosition=position();assertTrue("Actual older source needs a real contributor-list scroll",evidencePosition>0);Instrumentation.ActivityMonitor evidenceMonitor=i.addMonitor(RecordReportActivity.class.getName(),null,false);RecordReportActivity evidenceReport;try{contributor.click();evidenceReport=(RecordReportActivity)evidenceMonitor.waitForActivityWithTimeout(5000);assertNotNull("Observed contributor opens its actual read-only record",evidenceReport);}finally{i.removeMonitor(evidenceMonitor);}assertEquals(observedNight.record.id,evidenceReport.getIntent().getLongExtra("record",0));assertTrue(device.wait(Until.hasObject(By.desc("Edit sleep")),5000));capture("evidence-report",evidenceReport);assertTrue(device.pressBack());activity.awaitReaders(5000);i.waitForIdleSync();awaitPosition(evidencePosition);assertTrue(device.hasObject(By.desc(observed)));capture("evidence-returned");recreate("Timing evidence");activity.awaitReaders(5000);i.waitForIdleSync();awaitPosition(evidencePosition);assertTrue(device.hasObject(By.desc(observed)));capture("evidence-recreated");click("Older observed nights");String oldest="Open observed night "+oldestNight.day+", "+oldestNight.record.provenance();assertNotNull("Second page contains its actual remaining source",object(oldest));assertTrue(device.hasObject(By.text("Observed nights 21–21 of 21")));capture("evidence-older-page");recreate("Timing evidence");activity.awaitReaders(5000);i.waitForIdleSync();assertNotNull(object(oldest));assertTrue("Observed evidence page survives recreation",device.hasObject(By.text("Observed nights 21–21 of 21")));click("Newer observed nights");assertTrue(device.wait(Until.hasObject(By.text("Observed nights 1–20 of 21")),5000));object("Back").click();assertTrue(device.wait(Until.hasObject(By.text("Review observed timing evidence")),5000));assertTrue(new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().text("More recorded nights needed")));assertTrue(device.hasObject(By.text("More recorded nights needed")));try(Store store=new Store(c,name)){assertEquals("Contributor review never changes source rows or record overlays",fixture,store.backup().toString());}
            object("Workday schedule").click();object("Monday").click();object("Saturday").click();assertFalse(object("Monday").isChecked());assertTrue(object("Saturday").isChecked());capture("workdays");recreate("Save workdays");assertFalse(object("Monday").isChecked());assertTrue(object("Saturday").isChecked());assertTrue(prefs.getAll().isEmpty());capture("recreated");click("Save workdays");assertTrue(device.wait(Until.hasObject(By.descStartsWith("Bedtime range ")),5000));assertEquals(62,RhythmSettings.read(prefs));assertEquals(Set.of("rhythmWorkdays"),prefs.getAll().keySet());
            try(Store store=new Store(c,name)){RhythmStats expected=new RhythmStats(Records.all(store),Prefs.number(c,"statsCutoff",0),62,now);String gap="Social jetlag "+RecordUi.duration(RhythmStats.displayGapMillis(expected.workMidpoint,expected.freeMidpoint));assertTrue(device.hasObject(By.desc(gap)));assertEquals(fixture,store.backup().toString());}finish();launch();object("Workday schedule").click();assertFalse(object("Monday").isChecked());assertTrue(object("Saturday").isChecked());object("Monday").click();object("Back").click();assertTrue(device.wait(Until.hasObject(By.descStartsWith("Bedtime range ")),5000));assertEquals(62,RhythmSettings.read(prefs));capture("reopened");finish();
            try(Store store=new Store(c,name)){store.eraseHistory();}launch();assertTrue(device.hasObject(By.text("No main nights yet")));assertTrue(device.hasObject(By.text("0 of 30 nights")));assertFalse("An unknown empty date cannot open an invented night",device.hasObject(By.text("Open selected night")));capture("empty");click("Review observed timing evidence");assertTrue(device.wait(Until.hasObject(By.text("No eligible timing observations")),5000));assertFalse("No invented observed source action in empty history",device.hasObject(By.descStartsWith("Open observed night ")));capture("evidence-empty");assertEquals(originalPrefs,Prefs.of(c).getAll());assertFalse(AlarmService.active);assertFalse(TrackingService.running);try(java.io.PrintWriter receipt=new java.io.PrintWriter(new File(c.getExternalFilesDir(null),"verification/rhythm-evidence-proof.json"),"UTF-8")){receipt.println(new org.json.JSONObject().put("eligible_history_nights",21).put("latest_plotted_nights",7).put("chart_source_record",first.record.id).put("reviewed_source_record",observedNight.record.id).put("older_page_source_record",oldestNight.record.id).put("genuine_scrolled_return_and_recreation",true).put("older_page_recreated_and_newer_returned",true).put("source_snapshot_unchanged_by_review",true).put("chronotype_remains_unknown",true).put("empty_has_no_source_action",true).put("physical_outputs",false).toString(2));}
        }catch(Exception|AssertionError failure){try{File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());device.takeScreenshot(new File(folder,"rhythm-failure.png"));device.dumpWindowHierarchy(new File(folder,"rhythm-failure.xml"));}catch(Exception diagnostic){failure.addSuppressed(diagnostic);}throw failure;}finally{try{PlanOperations.drain(10000);i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});i.waitForIdleSync();for(Activity a:owned){if(a instanceof SleepRhythmActivity rhythm)rhythm.awaitReaders(5000);else if(a instanceof RecordReportActivity report)report.awaitReaders(5000);}long until=SystemClock.elapsedRealtime()+5000;while(owned.stream().anyMatch(a->!a.isDestroyed())&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);assertTrue(owned.stream().allMatch(Activity::isDestroyed));}finally{app.unregisterActivityLifecycleCallbacks(lifecycle);i.runOnMainSync(()->{Records.factory=priorRecords;RhythmSettings.factory=priorSettings;SleepRhythmActivity.clock=priorClock;});if(owned.stream().allMatch(Activity::isDestroyed)){c.deleteDatabase(name);c.deleteSharedPreferences(preferences);}}}
    }
}
